export declare const requestSMS = "\n<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\"/>\n\n<title>SMS Pack Request</title>\n\n<style>\n\nbody{\n  margin:0;\n  padding:20px;\n  background:#f5f7fa;\n  font-family:Arial, Helvetica, sans-serif;\n  color:#111827;\n}\n\n.container{\n  max-width:560px;\n  margin:auto;\n  background:#ffffff;\n  border:1px solid #e5e7eb;\n  border-radius:12px;\n  overflow:hidden;\n}\n\n.header{\n  padding:24px;\n  border-bottom:1px solid #e5e7eb;\n}\n\n.header h1{\n  margin:0;\n  font-size:22px;\n  color:#111827;\n}\n\n.header p{\n  margin:8px 0 0;\n  font-size:14px;\n  color:#6b7280;\n}\n\n.content{\n  padding:24px;\n}\n\n.info{\n  width:100%;\n  border-collapse:collapse;\n}\n\n.info td{\n  padding:12px 0;\n  border-bottom:1px solid #f1f5f9;\n  font-size:14px;\n}\n\n.label{\n  color:#6b7280;\n  width:40%;\n}\n\n.value{\n  color:#111827;\n  font-weight:600;\n}\n\n.note{\n  margin-top:20px;\n  padding:16px;\n  background:#f9fafb;\n  border-radius:10px;\n  font-size:14px;\n  line-height:1.6;\n  color:#374151;\n}\n\n.button{\n  margin-top:28px;\n  text-align:center;\n}\n\n.btn{\n  display:inline-block;\n  padding:12px 22px;\n  background:#111827;\n  color:#ffffff !important;\n  text-decoration:none;\n  border-radius:8px;\n  font-size:14px;\n  font-weight:600;\n}\n\n.footer{\n  padding:20px 24px;\n  border-top:1px solid #e5e7eb;\n  background:#fafafa;\n  font-size:12px;\n  color:#9ca3af;\n  text-align:center;\n}\n\n</style>\n</head>\n\n<body>\n\n<div class=\"container\">\n\n  <div class=\"header\">\n    <h1>SMS Pack Purchase Request</h1>\n    <p>A new SMS pack request has been submitted.</p>\n  </div>\n\n  <div class=\"content\">\n\n    <table class=\"info\">\n\n      <tr>\n        <td class=\"label\">Company</td>\n        <td class=\"value\">%company%</td>\n      </tr>\n\n      <tr>\n        <td class=\"label\">Quantity</td>\n        <td class=\"value\">%quantity% SMS</td>\n      </tr>\n\n      <tr>\n        <td class=\"label\">Request Date</td>\n        <td class=\"value\">%date%</td>\n      </tr>\n\n      <tr>\n        <td class=\"label\">Status</td>\n        <td class=\"value\">Pending Review</td>\n      </tr>\n\n    </table>\n\n    <div class=\"note\">\n      This request requires administrator validation before processing.\n    </div>\n\n    <div class=\"button\">\n      <a href=\"%dashboard_url%\" class=\"btn\">\n        View Request\n      </a>\n    </div>\n\n  </div>\n\n  <div class=\"footer\">\n    \u00A9 %year% %platform_name%\n  </div>\n\n</div>\n\n</body>\n</html>\n";
